create extension if not exists pgcrypto;
create schema if not exists auth;
create table if not exists auth.users(id uuid primary key default gen_random_uuid(), email text);
create or replace function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('test.uid', true),'')::uuid $$;
do $$ begin create role authenticated nologin; exception when duplicate_object then null; end $$;
do $$ begin create role anon nologin; exception when duplicate_object then null; end $$;
do $$ begin create role tester login; exception when duplicate_object then null; end $$;
-- service_role: esiste su Supabase (chiave service, salta la RLS); serve alla migrazione 30 e a stripe.php/webhook
do $$ begin create role service_role nologin bypassrls; exception when duplicate_object then null; end $$;
grant usage on schema public, auth to service_role;
alter default privileges in schema public grant all on tables to service_role;
alter default privileges in schema public grant all on sequences to service_role;
alter default privileges in schema public grant execute on functions to service_role;
-- tester fa le veci dell'admin: nei test crea gli account come farebbe Supabase Auth
grant select, insert, update, delete on auth.users to tester;
grant authenticated to tester; grant usage on schema public, auth to authenticated, anon;
create table edu_classi(codice text primary key, istituto text, comune text, livello text, anno_scolastico text, progetto text, note text, creato_il timestamp with time zone default now());
create table edu_eventi(id bigserial primary key, codice_classe text, progetto text, lezione text, tipo text, dettaglio jsonb default '{}'::jsonb, ts timestamp with time zone default now());
create table edu_hotspot(id uuid primary key default gen_random_uuid(), tappa_id uuid, yaw numeric, pitch numeric, em text, tit text, txt text, txt2 text, foto_url text, audio_url text, validazione text, validatore text, validato_il timestamp with time zone, ordine integer);
create table edu_lezioni(id uuid primary key default gen_random_uuid(), progetto text, slug text, titolo text, sottotitolo text, emoji text, colore text, durata_label text, intro text, ordine integer, stato text, owner uuid, origine_id uuid, token text, creato_il timestamp with time zone default now(), aggiornato_il timestamp with time zone default now(), video_coccio text, accessibilita jsonb, prologo text);
create table edu_mascotte(id uuid primary key default gen_random_uuid(), progetto text, chiave text, livello text, video text, attivo boolean default true, note text);
create table edu_media(id uuid primary key default gen_random_uuid(), lezione_id uuid, ordine integer, tipo text, guid text, url text, durata_s numeric, note text, video_lis text);
create table edu_messaggi(chiave text primary key, progetto text, titolo text, descrizione text, url text, attivo boolean default true, livello text, ordine integer, aggiornato_il timestamp with time zone default now());
create table edu_progetti(progetto text primary key, nome text, mascotte_nome text, mascotte_img text, mascotte_junior boolean, mascotte_senior boolean, quiz_sempre boolean, aggiornato_il timestamp with time zone default now());
create table edu_quiz(id uuid primary key default gen_random_uuid(), lezione_id uuid, livello text, domanda text, opzioni jsonb, ok integer, ordine integer, spiegazione text, media_spiegazione text, v integer);
create table edu_tappe(id uuid primary key default gen_random_uuid(), lezione_id uuid, media_id uuid, t numeric, cocciu text, cocciu2 text, ordine integer);
create table edu_utenti(id uuid primary key default gen_random_uuid(), ruolo text, istituto text, nome text, creato_il timestamp with time zone default now());
create table edu_versioni(id bigserial primary key, lezione_id uuid, dati jsonb, creato_da uuid, creato_il timestamp with time zone default now());
create view edu_v_report_istituti as select c.istituto, c.comune, count(distinct e.codice_classe) classi_attive, count(*) filter (where e.tipo='lezione_completata') lezioni_completate, count(*) filter (where e.tipo='lezione_avviata') lezioni_avviate from edu_classi c left join edu_eventi e on e.codice_classe=c.codice group by 1,2;
create view edu_v_report_moduli as select e.progetto, e.lezione, count(*) filter (where e.tipo='lezione_avviata') avviate, count(*) filter (where e.tipo='lezione_completata') completate, avg((e.dettaglio->>'pct')::numeric) media_quiz from edu_eventi e group by 1,2;
create or replace function edu_get_lezioni(p_progetto text) returns jsonb language sql stable security definer as $$ select coalesce(jsonb_agg(jsonb_build_object('id',slug,'tit',titolo,'stato',stato) order by ordine),'[]'::jsonb) from edu_lezioni where progetto=p_progetto and owner is null and stato<>'bozza' $$;
create or replace function edu_get_mascotte(p_progetto text) returns jsonb language sql stable security definer as $$ select coalesce(jsonb_object_agg(chiave, video),'{}'::jsonb) from edu_mascotte where progetto=p_progetto and attivo $$;
create or replace function edu_get_lezione_token(p_token text) returns jsonb language sql stable security definer as $$ select jsonb_build_object('id',slug) from edu_lezioni where token=p_token $$;
alter table edu_lezioni enable row level security; create policy lezioni_auth on edu_lezioni for all to authenticated using (true) with check (true);
alter table edu_eventi enable row level security; create policy eventi_anon_insert on edu_eventi for insert to anon with check (codice_classe ~ '^[A-Z0-9-]{1,20}$');
alter table edu_utenti enable row level security; create policy utenti_self on edu_utenti for select to authenticated using (id = auth.uid());
